local A="1w6hZsAlJTx7WOIz4o8QfN+mn5ugXcaMPektqCUdVSDrHRybGEpB9v3Y2iFj0LK/"
local K="AfH9_k26Zq"
local P={
"",
"",
"",
"",
"",
""
}
local D=""
for i=#P,1,-1 do D=D..P[i] end
local M={} for i=1,#A do M[A:sub(i,i)]=i-1 end
local acc,nb,out=0,0,{}
for c in D:gmatch(".") do local v=M[c] if v then acc=acc*64+v nb=nb+6 if nb>=8 then nb=nb-8 local p=2^nb out[#out+1]=string.char(acc//p%256) acc=acc%p end end end
local raw=table.concat(out)
local n=#K local kb={} for i=1,n do kb[i]=K:byte(i) end
local bx=(bit32 and bit32.bxor) or (bit and bit.bxor)
if not bx then
    bx=function(a,b) local r,p=0,1 for _=1,8 do local x,y=a%2,b%2 if x~=y then r=r+p end a=(a-x)/2 b=(b-y)/2 p=p*2 end return r end
end
local res={} for i=1,#raw do res[i]=string.char(bx(raw:byte(i),kb[(i-1)%n+1])) end
local f=loadstring or load
if not f then warn("[阿风脚本] 执行器不支持 loadstring") return end
local ok,e=pcall(function() f(table.concat(res))() end)
if not ok then warn("[阿风脚本] "..tostring(e)) end
